'use strict';
// Админка: «Учётные записи» и «Организации»
/* ═════════════ Админка ═════════════ */
const ORGS=DB.platformOrgs;
// Число контрагентов и сотрудников: у своей организации — живое, у остальных — из данных
function orgBind(o){Object.defineProperty(o,'cps',{value:()=>o.self?CPS.filter(c=>!c.archived).length:o.contractors||0,configurable:true});Object.defineProperty(o,'staff',{value:()=>o.self?EMP.filter(e=>e.active).length:o.employees||0,configurable:true});return o}
ORGS.forEach(orgBind);
const OTHER_USERS=DB.platformUsers;
function allUsers(){return [...EMP.map(e=>({_cb:e._cb,_ca:e._ca,_ub:e._ub,_ua:e._ua,login:e.login,fio:e.fio,org:'o1',role:ROLES.find(r=>r.id===e.role).name,lastIn:e.lastIn,active:e.active,ref:e})),...OTHER_USERS,{_cb:'system',_ca:'2025-01-10 09:00',login:'admin',fio:'Администратор платформы',org:null,role:'Администратор платформы',lastIn:'сейчас',active:true}]}
const orgName=id=>id?(ORGS.find(o=>o.id===id)||{}).name||'':'Платформа';
function renderAccounts(body,tab,fresh){
  body.innerHTML='<div id="ag"></div>';
  grid($('#ag',body),{id:'adm-users',rid:u=>u.login,cols:[{key:'login',label:'Логин',type:'text',w:150,val:u=>u.login,cls:'mono'},{key:'fio',label:'ФИО',type:'text',w:240,val:u=>u.fio,html:u=>`<span class="strong">${esc(u.fio)}</span>`},{key:'org',label:'Организация',type:'enum',w:240,val:u=>orgName(u.org)},{key:'role',label:'Роль',type:'enum',w:190,val:u=>u.role},{key:'last',label:'Последний вход',type:'text',w:150,val:u=>u.lastIn},{key:'active',label:'Статус',type:'enum',w:140,val:u=>u.active?'Активен':'Заблокирован',html:u=>u.active?pill('Активен',{Активен:['green','check']}):pill('Заблокирован',{Заблокирован:['red','lock']})}],
    rows:allUsers,title:'fio',noun:['учётная запись','учётные записи','учётных записей'],rowClass:u=>u.active?'':'muted',sort:{key:'org',dir:1},simulateLoad:fresh,open:u=>menu(document.querySelector(`[data-id="${CSS.escape(u.login)}"]`)||document.body,accActions(u)),actions:accActions});
}
function accActions(u){if(u.login==='admin')return [{label:'Это вы',icon:'user',disabled:true}];const setA=v=>{u.active=v;if(u.ref){u.ref.active=v;touch(u.ref)}else{const o=OTHER_USERS.find(x=>x.login===u.login);if(o){o.active=v;touch(o)}}renderPage();toast(v?'Учётная запись разблокирована':'Учётная запись заблокирована',v?'key':'lock')};
  return [{label:'Сбросить пароль',icon:'key',run:()=>openModal({render:()=>({title:'Пароль сброшен',sub:`${esc(u.fio)} · ${esc(u.login)}`,body:`<p style="margin:0">Временный пароль: <b class="mono" style="font-size:16px">${tmpPass()}</b></p><p class="muted" style="margin:0">Все сеансы пользователя завершены${u.ref&&u.ref.tg||!u.ref?', бот сообщил о смене пароля в Telegram':''}.</p>`,foot:'<button class="btn cta" data-close>Готово</button>'})})},{sep:true},
    u.active?{label:'Заблокировать',icon:'lock',danger:true,run:()=>confirmDlg({title:`Заблокировать ${esc(u.login)}?`,text:'Пользователь не сможет войти, его сеансы завершатся.',ok:'Заблокировать',danger:true,run:()=>setA(false)})}:{label:'Разблокировать',icon:'key',run:()=>setA(true)}]}
function renderOrgs(body,tab,fresh){
  body.innerHTML=`<div class="plates">${plate({id:'a',icon:'building',color:'blue',label:'Организаций',value:ORGS.filter(o=>o.active).length,sub:'активных'})}${plate({id:'b',icon:'users',color:'green',label:'Контрагентов на платформе',value:ORGS.reduce((a,o)=>a+o.cps(),0)})}${plate({id:'c',icon:'user',color:'purple',label:'Пользователей',value:allUsers().length-1})}${plate({id:'d',icon:'send',color:REQUESTS.length?'yellow':'green',label:'Запросы на добавление',value:REQUESTS.length,sub:'в справочники'})}</div><div id="og"></div>`;
  body.querySelector('.plates').onclick=e=>{const b=e.target.closest('[data-plate]');if(b&&b.dataset.plate==='d')go('pdicts','requests')};
  grid($('#og',body),{id:'adm-orgs',cols:[{key:'name',label:'Название',type:'text',w:280,val:o=>o.name,html:o=>`<span class="strong">${esc(o.name)}</span>`},{key:'inn',label:'ИНН',type:'text',w:150,val:o=>o.inn,cls:'mono'},{key:'owner',label:'Владелец (логин)',type:'text',w:160,val:o=>o.owner,cls:'mono'},{key:'slug',label:'Адрес страницы',type:'text',w:170,hide:true,val:o=>o.self?ORG.slug||'':o.slug||'',cls:'mono'},{key:'cps',label:'Контрагентов',type:'int',w:120,num:true,val:o=>o.cps()},{key:'staff',label:'Сотрудников',type:'int',w:120,num:true,val:o=>o.staff()},{key:'created',label:'Регистрация',type:'date',w:120,hide:true,val:o=>o.created},{key:'active',label:'Статус',type:'enum',w:150,val:o=>o.active?'Активна':'Заблокирована',html:o=>o.active?pill('Активна',{Активна:['green','check']}):`<span class="pill red" title="${esc(o.note||'')}">${ic('lock')}Заблокирована</span>`}],
    rows:()=>ORGS,title:'name',noun:['организация','организации','организаций'],rowClass:o=>o.active?'':'muted',sort:{key:'created',dir:1},simulateLoad:fresh,
    actions:o=>[o.active?{label:'Заблокировать',icon:'lock',danger:true,disabled:o.id==='o1',reason:o.id==='o1'?'Демо-организация прототипа':'',run:()=>confirmDlg({title:`Заблокировать ${esc(o.name)}?`,text:'Никто из сотрудников организации не сможет войти. Данные сохранятся, разблокировать можно в любой момент.',ok:'Заблокировать',danger:true,run:()=>{o.active=false;touch(o);o.note='Заблокирована администратором';renderPage();toast('Организация заблокирована','lock')}})}:{label:'Разблокировать',icon:'key',run:()=>{o.active=true;touch(o);renderPage();toast('Организация разблокирована')}}]});
}
function addOrgDlg(){openModal({form:true,size:'mid',render:()=>({title:'Новая организация',sub:'Создаётся вместе с учётной записью владельца',body:`<div class="form">${fld('Название',inp('no-name',''),{req:true,full:true,id:'no-name'})}${fld('ИНН',inp('no-inn','','class="inp mono" maxlength="14" inputmode="numeric"'),{req:true,id:'no-inn'})}<div></div>${fld('ФИО владельца',inp('no-fio',''),{req:true,id:'no-fio'})}${fld('Логин владельца',inp('no-login','','class="inp mono"'),{req:true,id:'no-login',hint:'Уникален на всей платформе'})}${fld('Временный пароль',inp('no-pass',tmpPass(),'class="inp mono" autocomplete="off"'),{req:true,id:'no-pass',hint:'Не короче 8 символов'})}</div><div class="note">${ic('info')}<span>Организация получит копии шаблонов ролей «Главный бухгалтер» и «Бухгалтер» и учётную политику по умолчанию.</span></div>`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="no-ok">Создать</button>',mount(el,m){$('#no-ok',el).onclick=()=>{const lg=val(el,'no-login').toLowerCase();const ok=[setErr(el,'no-name',val(el,'no-name')?'':'Введите название'),setErr(el,'no-inn',/^\d{14}$/.test(val(el,'no-inn'))?ORGS.some(o=>o.inn===val(el,'no-inn'))?'Организация с таким ИНН уже есть':'':'ИНН — 14 цифр'),setErr(el,'no-fio',val(el,'no-fio')?'':'Введите ФИО'),setErr(el,'no-login',!/^[a-z0-9._-]{3,}$/.test(lg)?'Латиница, цифры, точка, дефис; от 3 символов':allUsers().some(u=>u.login===lg)?'Такой логин уже занят на платформе':''),setErr(el,'no-pass',val(el,'no-pass').trim().length>=8?'':'Не короче 8 символов')].every(Boolean);if(!ok)return;
    const id='o'+(ORGS.length+1);ORGS.push(orgBind({_cb:S.me,_ca:nowStamp(),_ub:S.me,_ua:nowStamp(),id,name:val(el,'no-name'),inn:val(el,'no-inn'),slug:slugFree(slugOf(val(el,'no-name')),ORGS.map(o=>o.self?ORG.slug:o.slug).filter(Boolean)),owner:lg,created:TODAY,active:true,contractors:0,employees:1}));OTHER_USERS.push({_cb:S.me,_ca:nowStamp(),_ub:S.me,_ua:nowStamp(),login:lg,fio:val(el,'no-fio'),org:id,role:'Владелец организации',lastIn:'ещё не входил',active:true});m.close();renderPage();toast('Организация и владелец созданы','building')}}})})}

